  const minX = Math.min.apply(null, items.map(function (v) { return v.x; }));
  const minY = Math.min.apply(null, items.map(function (v) { return v.y; }));
  const maxX = Math.max.apply(null, items.map(function (v) { return v.x + v.w; }));
