  // 无连接卡片：没有 groupId，或 groupId 指向已不存在的组。
  const loose = [];
  s.images.forEach(function (im) { if (!getGroup(s, im.groupId)) loose.push({ id: im.id, kind: "image", obj: im }); });
  s.audios.forEach(function (a) { if (!getGroup(s, a.groupId)) loose.push({ id: a.id, kind: "audio", obj: a }); });
  const looseCol = tidyByPos(loose);

  const columns = [];
  unitCols.forEach(function (c) { columns.push(c); });
  if (looseCol.length) columns.push(looseCol);
