  if (s.promptOpen) { const p = s.promptPos || { x: 48, y: 96 }; const m = tidyMeasure("prompt", "prompt"); items.push({ id: "prompt", x: p.x, y: p.y, w: m.w, h: m.h, hc: panel.hc, bc: panel.bc, sc: panel.sc }); }
  if (s.boostOpen) { const p = s.boostPos || { x: 48, y: 400 }; const m = tidyMeasure("boost", "boost"); items.push({ id: "boost", x: p.x, y: p.y, w: m.w, h: m.h, hc: panel.hc, bc: panel.bc, sc: panel.sc }); }
  if (s.settingsOpen) { const p = s.settingsPos || { x: 48, y: 96 }; const m = tidyMeasure("settings", "settings"); items.push({ id: "settings", x: p.x, y: p.y, w: m.w, h: m.h, hc: panel.hc, bc: panel.bc, sc: panel.sc }); }
