function legacyCopy(text) {
  const ta = document.createElement("textarea");
  ta.value = text;
  ta.style.position = "fixed"; ta.style.opacity = "0";
  document.body.appendChild(ta);
  ta.select();
  try { document.execCommand("copy"); } catch { }
  ta.remove();
}
function copyText(text, which) {
  const s = S();
  const done = function () {
    if (which === "zh") s.copiedZh = true;
    else if (which === "en") s.copiedEn = true;
    else if (which === "link") s.copied = true;
    patchUI();
    __llSetTimeout(function () {
      if (which === "zh") s.copiedZh = false;
      else if (which === "en") s.copiedEn = false;
      else if (which === "link") s.copied = false;
      patchUI();
    }, 1500);
  };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(done).catch(function () { legacyCopy(text); done(); });
  } else { legacyCopy(text); done(); }
}
function copyZh() { const s = S(); if (s.zh.trim()) copyText(s.zh, "zh"); }
function copyEn() { const s = S(); if (s.en.trim()) copyText(s.en, "en"); }
function copyViewLink() { const s = S(); if (s.view && s.view.videoUrl) copyText(s.view.videoUrl, "link"); }

function transcribePayload(s, vision) {
  const lines = [];
  if (s.groups.length) {
    lines.push("角色/场景分组：" + s.groups.map(function (g) {
      const imgs = s.images.filter(function (i) { return i.groupId === g.id; }).map(function (i) { return i.name; });
      return (g.kind === "char" ? "角色" : "场景") + "「" + g.name + "」" +
        (imgs.length ? "（参考图：" + imgs.join("、") + "）" : "");
    }).join("；"));
  }
  const urlImgs = s.images.filter(function (im) { return im.kind === "url"; });
  const fileImgs = s.images.filter(function (im) { return im.kind === "file"; });
  if (urlImgs.length) lines.push(vision
    ? "参考图清单（已随本条消息附上图片，请逐张分析画面）：" + urlImgs.map(function (im) { return im.name; }).join("、")
    : "参考图清单（URL，请下载查看画面后分析）：" + urlImgs.map(function (im) { return im.name + "（" + im.url + "）"; }).join("；"));
  if (fileImgs.length) lines.push(vision
    ? "本地参考图 " + fileImgs.length + " 张（已随本条消息附上图片，请逐张分析画面）。"
    : "本地参考图 " + fileImgs.length + " 张（仅存于网页本地，你这边看不到画面；如需分析外观请告诉我，我另想办法发图）。");
  if (s.audios.length) lines.push("参考音频仅用于【素材绑定清单】里的声音来源标注（不随本条消息发送音频文件）。");
  lines.push("中文提示词：");
  let zhText = s.zh.trim();
  if (zhText.indexOf("【素材绑定清单】") < 0) zhText = zhText + "\n\n" + bindingText(s);
  lines.push(zhText);
  return lines.join("\n");
}

function bindingText(s) {
  const out = [];
  const chars = s.groups.filter(function (g) { return g.kind === "char"; });
  const scenes = s.groups.filter(function (g) { return g.kind === "scene"; });
  const order = chars.concat(scenes);
  const idxOf = {};
  order.forEach(function (g, i) { idxOf[g.id] = i + 1; });
  const imgOf = {};
  s.images.forEach(function (im, i) { imgOf[im.id] = i; });
  const audOf = {};
  s.audios.forEach(function (a, i) { audOf[a.id] = i; });
  order.forEach(function (g) {
    s.images.filter(function (im) { return im.groupId === g.id; }).forEach(function (im) {
      out.push('"ref_image_' + imgOf[im.id] + '"是"' + g.name + '"');
    });
    s.audios.filter(function (a) { return a.groupId === g.id; }).forEach(function (a) {
      out.push('"ref_audio_' + audOf[a.id] + '"是"' + g.name + '"的声音');
    });
  });
  s.images.filter(function (im) { return !idxOf[im.groupId]; }).forEach(function (im) {
    out.push('"ref_image_' + imgOf[im.id] + '"是场景/环境参考（未绑定角色）');
  });
  s.audios.filter(function (a) { return !idxOf[a.groupId]; }).forEach(function (a) {
    out.push('"ref_audio_' + audOf[a.id] + '"是环境音/独立音频（未绑定角色）');
  });
  if (order.length) {
    const map = order.map(function (g, i) { return g.name + "→<Subject " + (i + 1) + ">"; }).join("、");
    out.push("编号规则：" + map + "；\"ref_image_K\" 输出里是 <Picture K+1>；\"ref_audio_K\" 输出里是 <Audio K+1>；正文指代一律用 <Subject N>，禁止 the woman / the man 等代称。");
  } else {
    out.push("编号规则：正文指代一律用 <Subject N>，禁止 the woman / the man 等代称。");
  }
  out.push("无字幕无背景音乐");
  return "【素材绑定清单】\n" + out.join("\n");
}

function stripBindingFromZh(zh) {
  const idx = zh.indexOf("【素材绑定清单】");
  return (idx >= 0 ? zh.slice(0, idx) : zh).trim();
}

function oneClickBind() {
  const s = S();
  let zhText = stripBindingFromZh(s.zh.trim());
  if (zhText) zhText += "\n\n";
  s.zh = zhText + bindingText(s);
  persistState(s);
  render();
  toast("已写入【素材绑定清单】→ 角色按 角色1/角色2… 对应 <Subject 1>/<Subject 2>");
}

function dataUrlBytes(d) {
  const i = d.indexOf("base64,");
  if (i < 0) return d.length;
  const b64 = d.slice(i + 7).replace(/=+$/, "");
  return Math.floor(b64.length * 3 / 4);
}

function imgLoadable(url) {
  return new Promise(function (res) {
    const im = new Image();
    let done = false;
    const finish = function (ok) {
      if (done) return;
      done = true;
      im.onload = im.onerror = null;
      res(ok);
    };
    im.onload = function () { finish(true); };
    im.onerror = function () { finish(false); };
    __llSetTimeout(function () { finish(false); }, 8000);
    im.src = url;
  });
}

async function dsContent(s) {
  const parts = [{ type: "text", text: transcribePayload(s, true) }];
  let total = 0;
  let skipped = 0;
  for (let k = 0; k < s.images.length; k++) {
    const im = s.images[k];
    let bytes = 0;
    if (im.kind === "file") bytes = dataUrlBytes(im.url);
    if (bytes > DS_IMG_MAX_MB * 1024 * 1024) { skipped++; continue; }
    if (bytes && total + bytes > DS_TOTAL_MAX_MB * 1024 * 1024) { skipped++; continue; }
    if (im.kind === "url") {
      const ok = await imgLoadable(im.url);
      if (!ok) { skipped++; continue; }
    }
    if (bytes) total += bytes;
    parts.push({ type: "image_url", image_url: { url: im.url } });
  }
  if (skipped) parts.push({ type: "text", text: "（注意：有 " + skipped + " 张参考图未随消息附上——体积超限或链接无法访问，请按提示词文字与【素材绑定清单】描述处理，不要凭空编造外观。）" });
  return parts;
}

function oneClickTranscribe() {
  const s = S();
  const zhText = s.zh.trim();
  if (!zhText || s.transcribing) return;
  if (dskey.trim()) { transcribeDeepSeek(s); return; }
  const lines = [];
  lines.push("【一键转写 · 牢络生成平台公开版 · 线 " + s.n + "】");
  lines.push("请把下面的中文提示词转写成「六段式英文 JSON」用于 AI 视频生成。只输出一个 JSON 对象（不要 markdown 围栏、不要任何解释），字段固定为：");
  lines.push("  subject_definitions: 数组，逐一定义画面主体，每个主体含 name / appearance（外观只描述参考图中真实可见的特征，禁止凭空编造）/ clothing / role 等；");
  lines.push("  summary: 一句话画面概要；");
  lines.push("  retention_analysis: 主体一致性要求（服饰、样貌、比例、道具在镜头间保持一致）；");
  lines.push("  detailed_description: 逐镜头详细描述（镜头编号、景别、运镜、主体动作与对白；对白格式 <Subject N> (Sx) says, <d>[Language]…</d>）；");
  lines.push("  overall_soundscape: 整体音景（环境声、物体声、拟音等）；");
  lines.push("  non_diegetic_music: 非叙事音乐（曲风、乐器、情绪起落），没有就写无。");
  lines.push("硬性规则：人物一律按【素材绑定清单】写作 <Subject 1>、<Subject 2>……对应 角色1、角色2……；正文指代一律用 <Subject N>，禁止 the woman / the man 等代称；禁止使用 shouts；镜头数按 4-6s≤2镜、7-10s≤3镜、11-15s≤5镜 控制。");
  lines.push("台词与字幕规则：中文提示词里引号（“”）内的台词必须原样保留，一个字不改（含错别字与语气词）；角色开口对白用中文，写 says in Chinese, <d>[Chinese]台词</d>；【素材绑定清单】末尾的「无字幕无背景音乐」是硬要求——画面不得出现字幕，non_diegetic_music 写 N/A。");
  lines.push(transcribePayload(s));
  copyText(lines.join("\n"), "trans");
  s.transcribing = true;
  patchUI();
  __llSetTimeout(function () { s.transcribing = false; patchUI(); }, 1800);
  toast("未填 DeepSeek Key → 已复制请求，粘贴到任意 AI 助手（ChatGPT / 豆包 / Kimi 等）发送");
}

async function transcribeDeepSeek(s) {
  s.transcribing = true;
  patchUI();
  const call = async function (withImages, maxTok) {
    const userContent = withImages
      ? await dsContent(s)
      : [{ type: "text", text: transcribePayload(s, true) + "\n（附带的参考图未能被服务器读取，本次按纯文字转写；主体外观请以绑定清单与文字为准，禁止凭空编造。）" }];
    const r = await fetch(DS_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + dskey.trim() },
      body: JSON.stringify({
        model: DS_MODEL,
        messages: [
          { role: "system", content: DS_SYSTEM },
          { role: "user", content: userContent }
        ],
        temperature: 0.7,
        max_tokens: maxTok || 16384,
        thinking: { type: "disabled" },
        reasoning_effort: "none",
        response_format: { type: "json_object" }
      })
    });
    let j = null;
    try { j = await r.json(); } catch { j = {}; }
    return { r: r, j: j };
  };
  try {
    let ret = await call(true);
    if (!ret.r.ok) {
      const authOrBill = ret.r.status === 401 || ret.r.status === 402;
      const hadImages = ret.r.status === 413 || ((ret.j && ret.j.error && ret.j.error.message || "").indexOf("image") >= 0);
      if (!authOrBill && hadImages) ret = await call(false);
      if (!ret.r.ok) {
        let msg = (ret.j && ret.j.error && ret.j.error.message) ? ret.j.error.message : ("HTTP " + ret.r.status);
        if (ret.r.status === 401) msg = "DeepSeek Key 无效（检查密钥框里的 Key）";
        else if (ret.r.status === 402) msg = "DeepSeek 账户余额不足";
        else if (ret.r.status === 413) msg = "参考图太大，超出载荷上限（合计≤48MB）";
        toast("转写失败：" + msg);
        return;
      }
    }
    let fr = (ret.j && ret.j.choices && ret.j.choices[0] && ret.j.choices[0].finish_reason) || "";
    if (fr === "length") {
      const ret2 = await call(true, 32768);
      if (ret2.r.ok) ret = ret2;
    }
    fr = (ret.j && ret.j.choices && ret.j.choices[0] && ret.j.choices[0].finish_reason) || "";
    let content = (ret.j && ret.j.choices && ret.j.choices[0] && ret.j.choices[0].message && ret.j.choices[0].message.content) || "";
    content = String(content).trim().replace(/^```(json)?\s*/i, "").replace(/\s*```$/, "").trim();
    const m = content.match(/\{[\s\S]*\}/);
    if (m) content = m[0];
    s.en = content;
    persistState(s);
    render();
    toast(fr === "length" ? "转写完成，但输出疑似仍被截断——缺段落就再点一次" : "DeepSeek 转写完成 → 检查后点「应用到描述词」");
  } catch (e) {
    toast("转写失败：网络错误（" + (e && e.message ? e.message : "未知") + "）");
  } finally {
    s.transcribing = false;
    patchUI();
  }
}

