async function downloadVideo() {
  const s = S();
  const v = s.view;
  if (!v || !v.videoUrl) return;
  const url = v.localVideoUrl || v.videoUrl;
  toast("开始下载视频…");
  try {
    const r = await fetch(url);
    if (!r.ok) throw new Error("http " + r.status);
    const b = await r.blob();
    const u = URL.createObjectURL(b);
    const a = document.createElement("a");
    a.href = u;
    a.download = "牢络_" + ts2str(Date.now()) + ".mp4";
    document.body.appendChild(a);
    a.click();
    a.remove();
    __llSetTimeout(function () { URL.revokeObjectURL(u); }, 60000);
  } catch (e) {
    toast("直链下载被拦，已在新标签页打开（可在播放器右键另存为）");
    window.open(url, "_blank");
  }
}

function toast(msg) {
  const t = document.createElement("div");
  t.className = "uv-toast";
  t.textContent = msg;
  app.appendChild(t);
  __llSetTimeout(function () { t.remove(); }, 2600);
}

