function validateBatchShot(prompt, imgCount) {
  const p = (prompt || "").trim();
  if (!p) return "提示词为空，不能提交";
  if (imgCount < 1) return "没有参考图，不能提交";
  // [Shot] 编号只看 detailed_description 段内的镜头标记：
  // retention_analysis 里的 appears in [Shot N] 是引用、不是镜头
  // 标记，计入会把每个 H3 镜头都误判成编号不连续。段头找不到
  // 时退回全文扫（非 H3 文本口径不变）。
  let shotScope = p;
  const ddStart = p.indexOf("detailed_description:");
  if (ddStart >= 0) {
    const ddEnd = p.indexOf("overall_soundscape:", ddStart);
    shotScope = ddEnd > ddStart ? p.slice(ddStart, ddEnd) : p.slice(ddStart);
  }
  const shotNums = [];
  const reShot = /\[Shot\s+(\d+)\]/g;
  let m;
  while ((m = reShot.exec(shotScope)) !== null) shotNums.push(parseInt(m[1], 10));
  for (let i = 0; i < shotNums.length; i++) {
    if (shotNums[i] !== i + 1) return "分镜编号不连续（第 " + (i + 1) + " 个是 [Shot " + shotNums[i] + "]）";
  }
  const openD = (p.match(/<d>/g) || []).length;
  const closeD = (p.match(/<\/d>/g) || []).length;
  if (openD !== closeD) return "台词标签 <d> 不成对";
  if (openD > 0) {
    const parts = p.split("<d>");
    for (let i = 1; i < parts.length; i++) {
      const before = parts[i - 1].slice(-240);
      if (!/<Subject\s+\d+>\s*\(S\d+(,S\d+)*\)/.test(before)) {
        return "第 " + i + " 句台词前面没写说话人";
      }
    }
    const subjNums = [];
    const reSubj = /<Subject\s+(\d+)>/g;
    while ((m = reSubj.exec(p)) !== null) subjNums.push(parseInt(m[1], 10));
    const uniq = Array.from(new Set(subjNums)).sort(function (a, b2) { return a - b2; });
    for (let i = 0; i < uniq.length; i++) {
      if (uniq[i] !== i + 1) return "人物编号不连续（缺 <Subject " + (i + 1) + ">）";
    }
  }
  return null;
}

