  try {
    resp = await fetch(url);
  } catch (err) {
    throw new Error("拉取图片网络失败 (" + String((err && err.message) || err) + ")");
  }
  if (!resp || !resp.ok) {
    throw new Error("拉取图片未成功（状态码 " + (resp ? resp.status : "未知") + "）");
  }
  const blob = await resp.blob();
  if (!blob || !blob.size) {
    throw new Error("拉取到的图片内容为空 (0 bytes)");
  }
  const compressed = await compressRefImage(url);
  if (!compressed) {
    throw new Error("图片压缩编码后为空");
  }
