  const archCount = archRecs.length;
  const projName = sbProjectName(b.projectId) || b.projectName || (b.projectId != null ? "项目" + b.projectId : "当前项目");
  const curSeq = viewRec ? viewRec.seqNum : b.seqNum || 0;
  // v6.63 四区布局（推倒重做）：Zone 1 顶栏 52px（标题 + 项目切
  // 换 pill + 存档 pill 在左，收起/× 在右）；Zone 2 配置两行；
  // Zone 3 镜头列表独立滚动；Zone 4 底部 footer 固定 60px（统
