    '<button class="uv-barch-btn' + (b.archDrawerOpen ? " open" : "") + '" data-fid="batch-arch-btn" onclick="batchToggleArchiveDrawer()" aria-label="打开或收起批量生成记录列表">📁 生成记录 (' + archCount + ")" + (curSeq ? " · #" + curSeq : "") + " ▾</button>" +
    '</div><div class="uv-batch-head-right">' +
    '<button class="uv-btn small" data-fid="batch-minimize-btn" onclick="batchToggleCollapse()">收起</button>' +
    '<button class="uv-btn small" onclick="closeBatchPanel()" aria-label="关闭批量生成窗口">×</button></div></div>';
  // 项目菜单 / 存档抽屉打开时才挂背板与本体（条件渲染，根因
